from datetime import date

def add_months(day: str, n: int) -> str:
    # Parse the input date
    year, month, day_of_month = map(int, day.split('-'))

    # Calculate new month and year
    new_month = month + n
    new_year = year

    # Normalize month and year
    while new_month > 12:
        new_month -= 12
        new_year += 1

    while new_month < 1:
        new_month += 12
        new_year -= 1

    # Get the last day of the original month
    if month == 12:
        last_day_original = 31
    else:
        # Find last day of current month
        if month in [1, 3, 5, 7, 8, 10, 12]:
            last_day_original = 31
        elif month in [4, 6, 9, 11]:
            last_day_original = 30
        else:  # February
            if (year % 4 == 0 and year % 100 != 0) or (year % 400 == 0):
                last_day_original = 29
            else:
                last_day_original = 28

    # Check if original day was the last day of its month
    is_last_day = (day_of_month == last_day_original)

    # Get the last day of the target month
    if new_month in [1, 3, 5, 7, 8, 10, 12]:
        last_day_target = 31
    elif new_month in [4, 6, 9, 11]:
        last_day_target = 30
    else:  # February
        if (new_year % 4 == 0 and new_year % 100 != 0) or (new_year % 400 == 0):
            last_day_target = 29
        else:
            last_day_target = 28

    # Determine the day of the target month
    if is_last_day:
        new_day = last_day_target
    else:
        new_day = min(day_of_month, last_day_target)

    # Format and return the result
    return f"{new_year:04d}-{new_month:02d}-{new_day:02d}"
